UPDATE lessons SET title='Year 8, Week 34, Lesson 4: Probability problems', data=json_patch(data,'{"child_mission":"Stage 4 Mathematics develops fluent reasoning for probability problems. Students choose a valid method, show working, and check reasonableness. Catalogue alignment uses MA4-ARI-C-01. Prefer exact reasoning over guessing.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nFor probability problems, solve a guided problem with visible working and a one-sentence reason for the method.\n\nFEEDBACK\nStrong answer: method named, working complete, result checked for reasonableness.\n\nWATCH FOR\nSkipping working for probability problems, or mixing units/places without checking.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nIndependently complete a substantial task on probability problems: solve several new items with working, include one deliberate error-analysis, and write a short reflection on a method choice.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Stage 4 Mathematics develops fluent reasoning for probability problems. Students choose a valid method, show working, and check reasonableness. Catalogue alignment uses MA4-ARI-C-01. Prefer exact reasoning over guessing.","lesson_number":4,"lesson_role":"Fluency and review","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA4-ARI-C-01"],"parent_notes":"Parent: Marking guidance for the independent task: Independently complete a substantial task on probability problems: solve several new items with working, include one deliberate error-analysis, and write a short reflection on a method choice. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for probability; key places/values named. Do not award marks for retyping the model.\n\nParent: Written model 2: Sample misconception: Skipping working for probability problems, or mixing units/places without checking.. Correction uses Strong answer: method named, working complete, result checked for reasonableness.. Why: restores accurate probability.\n\nParent: Likely misconception: Skipping working for probability problems, or mixing units/places without checking. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses probability with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with probability, show corrected working, and say why the correction works.\n\nParent: Marking notes: Accept any mathematically valid solution that uses new numbers, shows working for probability, and names places/values. Reject copied model numbers. / Accept a named misconception about probability, corrected working, and a method reason. Reject vague “I was wrong” with no repair..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"This matches the taught method for probability. The other choices miss a key step or use a common mistake.","options":["Ignore place value and read digits from left to right as ones only.","Treat a missing zero as if it does not change the value.","method named, working complete, result checked for reasonableness.","Skipping working for probability problems, or mixing units/places without checking."],"question":"For probability problems, solve a guided problem with visible working and a one-sentence reason for the method. Which response is most accurate?","type":"multiple_choice"},{"correct_index":3,"explanation":"This is the misconception to avoid for probability; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Stage 4 Mathematics develops fluent reasoning for probability problems.","method named, working complete, result checked for reasonableness.","Careful use of problems with clear evidence.","Skipping working for probability problems, or mixing units/places without checking."],"question":"Which statement is a common mistake when working with probability?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and a named problems, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Repeat the worked example wording with no new evidence.","Skipping working for probability problems, or mixing units/places without checking.","Name problems only, without linking it to probability.","Apply probability to new material and name the problems used."],"question":"Which response best applies probability with new evidence?","type":"multiple_choice"},{"correct_index":1,"explanation":"Mathematics answers need labelled working tied to place value, quantity or the asked operation. The other choices miss a key step or use a common mistake.","options":["Skipping working for probability problems, or mixing units/places without checking.","Show each place, value or step and say why that step is valid.","Write only a final number with no working.","Change digits to look neater without checking place value."],"question":"Which working best supports a correct answer for this lesson on probability?","type":"multiple_choice"},{"correct_index":0,"explanation":"The correct statement applies the taught probability method; the others break place value, units or the asked quantity. The other choices miss a key step or use a common mistake.","options":["method named, working complete, result checked for reasonableness.","Skipping working for probability problems, or mixing units/places without checking.","Read 24 from left to right as ones only, ignoring place value.","Ignore units and treat 24 and 6 as interchangeable."],"question":"Using the method for probability, which statement is true?","type":"multiple_choice"},{"correct_index":3,"explanation":"Disagreement is resolved by checking places, operations and the question focus, not by blending answers. The other choices miss a key step or use a common mistake.","options":["Pick the longer-looking working automatically.","Delete units so the answers appear to match.","Average the two answers without checking either.","Recheck places, operations and whether the question asked for the quantity you computed."],"question":"If two methods disagree on a probability problem with numbers such as 24 and 6, what should you check first?","type":"multiple_choice"},{"correct_index":1,"explanation":"Transfer requires new numbers with the same mathematical method and a named reason. The other choices miss a key step or use a common mistake.","options":["Skipping working for probability problems, or mixing units/places without checking.","Use the same probability method on new numbers and name the places or values that matter.","Retype the worked model numbers 24 and 6 as the answer.","Change only handwriting and keep the same numbers."],"question":"Solve a multi-step probability problem with different values from the model, justify each step, and check reasonableness.?","type":"multiple_choice"},{"correct_index":1,"explanation":"Recognising the warned misconception protects accuracy on new problems. The other choices miss a key step or use a common mistake.","options":["Label units when comparing 24 with 6.","Skipping working for probability problems, or mixing units/places without checking.","Stage 4 Mathematics develops fluent reasoning for probability problems.","method named, working complete, result checked for reasonableness."],"question":"Which error is the lesson warning against for probability?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept any mathematically valid solution that uses new numbers, shows working for probability, and names places/values. Reject copied model numbers.","question":"Solve one fresh problem that uses probability with different numbers from the worked model. Show working and name the places or values that matter.","sample_answer":"Sample: new numbers solved with visible working for probability; key places/values named. Do not award marks for retyping the model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a named misconception about probability, corrected working, and a method reason. Reject vague “I was wrong” with no repair.","question":"Describe one likely mistake with probability, show corrected working, and say why the correction works.","sample_answer":"Sample misconception: Skipping working for probability problems, or mixing units/places without checking.. Correction uses Strong answer: method named, working complete, result checked for reasonableness.. Why: restores accurate probability.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent working and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s4-mat-y8-w34-l4","sort_activity":null,"source_note":"Proposed Stage 2 NESA mathematics alignment using verified outcome code wording where recorded in lesson-pipeline/sources; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S4","stage_hints":{"accept":["Today you will practise probability.","Read the mission before you start calculating.","Keep the place or unit you are working with in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your working with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the place or distance that carries the method.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore place value or working.","Prefer accurate method over a guess that merely looks neat."],"submit":["Confirm that your working and reason are both present.","Proofread digits, places and operation signs.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact place, value or distance before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key numbers.","Say what each number represents in the method.","A final answer alone is weaker than labelled working."],"teach2":["Compare a weak attempt with stronger working.","Change the value or method, not only how neat it looks.","Name the mistake you are repairing."],"teach3":["Choose fresh numbers that still use the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original working and a short reason.","Save work that shows the skill on new numbers."]},"subject":"Probability","success_criteria":["I can use probability with a specific example from this lesson.","I can identify problems and explain why it matters.","I can practise method independently on a new prompt.","I can notice accuracy needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Stage 4 Mathematics develops fluent reasoning for probability problems.","options":["Stage 4 Mathematics develops fluent reasoning for probability problems.","A calculation unrelated to the numbers given.","An answer copied without understanding.","A guess with no working."],"question":"Which choice best shows accurate use of this idea about probability?","type":"multiple_choice"},"example":"WORKED MODEL\nExample for Probability problems: state the values, show the method step by step, and check the result. Weak: an answer with no working.\n\nTRY FIRST\nFor probability problems, solve a guided problem with visible working and a one-sentence reason for the method.\n\nFEEDBACK\nStrong answer: method named, working complete, result checked for reasonableness.","explain":"Stage 4 Mathematics develops fluent reasoning for probability problems. Students choose a valid method, show working, and check reasonableness. Catalogue alignment uses MA4-ARI-C-01. Prefer exact reasoning over guessing.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Skipping working for probability problems, or mixing units/places without checking. Correct the value or method, not just the appearance of the digits.","title":"Understand and model","visual":[{"alt":"Probability problems.","caption":"Check reasonableness.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Values</text><text x=\"28\" y=\"78\">Probability problems</text><text x=\"358\" y=\"42\">Method</text><text x=\"358\" y=\"78\">shown working</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which number or place matters most.","who":"pip"},{"text":"Name the places, values or distances that carry the method before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Example for Probability problems: state the values, show the method step by step, and check the result. Weak: an answer  Then write your own working.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which number or place matters most.\nJuno: Name the places, values or distances that carry the method before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Example for Probability problems: state the values, show the method step by step, and check the result. Weak: an answer  Then write your own working."}}]},{"check":{"correct_index":0,"explanation":"Make the method visible: name the values, places or steps you used and say why that step is valid. Supported working follows the actual numbers and purpose of the task. The other choices miss a key step or use a common mistake.","options":["Make the method visible: name the values, places or steps you used and say why that step is valid.","A calculation unrelated to the numbers given.","An